import { spawnSync } from "child_process";
import { parse as parseYaml } from "yaml";
import type { Task } from "./types/task.js";

/** Statuses where the authoritative state lives on main, not a feature branch. */
export const TERMINAL_STATUSES = new Set(["done", "cancelled"]);

/**
 * Delete a local branch if it exists but has no remote counterpart.
 * Called after tryReadTaskFromBranch returns null to clean up orphaned local branches
 * left behind when a remote branch is deleted (e.g. after squash-merge).
 */
export function deleteLocalBranchIfOrphan(workspaceRoot: string, branch: string): boolean {
  const listResult = spawnSync(
    "git",
    ["-C", workspaceRoot, "branch", "--list", branch],
    { encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] },
  );
  if (!listResult.stdout.trim()) return false;
  const deleteResult = spawnSync(
    "git",
    ["-C", workspaceRoot, "branch", "-D", branch],
